  "#define IN(loc) layout(location = loc) in\n"
  "#define OUT(loc) out\n"
  "#define IN_F(loc) in\n"
  "#define OUT_COLOR out vec4 o_color;\n"
  "#define VERTEX 1\n"
  "// The lit pass: a textured surface with one directional light. Used by the floor, the pillars, the\n"
  "// spinning boxes and the backdrop, which is where the per-draw uniform traffic comes from.\n"
  "uniform mat4 u_view_proj;\n"
  "uniform mat4 u_model;\n"
  "uniform vec4 u_tint;\n"
  "uniform vec4 u_light;\n"
  "uniform sampler2D u_texture;\n"
  "\n"
  "#ifdef VERTEX\n"
  "IN(0) vec3 a_position;\n"
  "IN(1) vec3 a_normal;\n"
  "IN(2) vec2 a_uv;\n"
  "OUT(0) vec3 v_normal;\n"
  "OUT(1) vec2 v_uv;\n"
  "void main() {\n"
  "  v_normal = mat3(u_model) * a_normal;\n"
  "  v_uv = a_uv;\n"
  "  gl_Position = u_view_proj * u_model * vec4(a_position, 1.0);\n"
  "}\n"
  "#else\n"
  "IN_F(0) vec3 v_normal;\n"
  "IN_F(1) vec2 v_uv;\n"
  "OUT_COLOR\n"
  "void main() {\n"
  "  float lambert = max(dot(normalize(v_normal), normalize(u_light.xyz)), 0.0);\n"
  "  vec4 albedo = texture(u_texture, v_uv) * u_tint;\n"
  "  o_color = vec4(albedo.rgb * (0.35 + 0.65 * lambert), u_tint.a);\n"
  "}\n"
  "#endif\n";
